      if (!state.submitted) {
        updateStatus("");
        return;
      }

      const hasErrors = fieldConfigs.some(
        (field) => Boolean(validateField(field.name, state.values[field.name]))
      );

      if (hasErrors) {
        updateStatus("Please correct the highlighted fields and submit again.");
        return;
      }

      updateStatus("");
    }

    function updateStatus(message, status = "") {
      const statusNode = document.getElementById("form-status");
      statusNode.textContent = message;
      if (status) {
        statusNode.dataset.status = status;
      } else {
        delete statusNode.dataset.status;
      }
    }

    function validateAllFields() {
      const nextErrors = {};

      fieldConfigs.forEach((field) => {
        const error = validateField(field.name, state.values[field.name]);
        if (error) {
          nextErrors[field.name] = error;
        }
      });

      state.errors = nextErrors;
      fieldConfigs.forEach((field) => updateFieldUI(field.name));
      return nextErrors;
    }

    function bindForm() {
      const form = document.getElementById("support-form");

      fieldConfigs.forEach((field) => {
        const input = document.getElementById(field.name);
        input.addEventListener("input", (event) => {
          state.values[field.name] = event.target.value;
          state.errors[field.name] = validateField(field.name, event.target.value);
          updateFieldUI(field.name);
          syncStatusMessage();
        });

        input.addEventListener("blur", (event) => {
          state.values[field.name] = event.target.value;
          state.errors[field.name] = validateField(field.name, event.target.value);
          updateFieldUI(field.name);
          syncStatusMessage();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        const errors = validateAllFields();
        const firstInvalidField = fieldConfigs.find((field) => errors[field.name]);

        if (firstInvalidField) {
          updateStatus("Please correct the highlighted fields and submit again.");
          document.getElementById(firstInvalidField.name).focus();
          return;
        }

        updateStatus("Thanks. Your support request has been submitted.", "success");
        form.reset();
        state.submitted = false;
        state.values = {
          fullName: "",
          email: "",
          phone: ""
        };
        state.errors = {};
        fieldConfigs.forEach((field) => updateFieldUI(field.name));
      });
    }

    function render() {
      document.getElementById("app").innerHTML = SupportPage();
      bindForm();
    }

    render();
  </script>
