<body>
  <div id="app"></div>
  <script type="module">
    const fieldConfigs = [
      {
        id: "fullName",
        name: "fullName",
        type: "text",
        label: "Full name",
        autocomplete: "name",
        placeholder: "Jordan Lee",
        required: true
      },
      {
        id: "email",
        name: "email",
        type: "email",
        label: "Email address",
        autocomplete: "email",
        placeholder: "jordan@example.com",
        required: true
      },
      {
        id: "phone",
        name: "phone",
        type: "tel",
        label: "Phone number",
        autocomplete: "tel",
        inputMode: "tel",
        placeholder: "(555) 123-4567",
        required: false,
        helperText: "Optional. Enter digits with spaces, dashes, or parentheses, for example (555) 123-4567."
      }
    ];

    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      errors: {},
      submitted: false
    };

    function FormField(config) {
      const helperId = config.helperText ? config.id + "-help" : "";
      const errorId = config.id + "-error";
      const describedBy = [helperId, errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <div class="field-label-row">
            <label class="field-label" for="${config.id}">
              ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <span class="field-note">${config.required ? "Required" : "Optional"}</span>
          </div>
          <input
            class="field-input"
            id="${config.id}"
            name="${config.name}"
            type="${config.type}"
            autocomplete="${config.autocomplete || ""}"
            ${config.inputMode ? `inputmode="${config.inputMode}"` : ""}
            placeholder="${config.placeholder || ""}"
            ${config.required ? "required aria-required=\"true\"" : ""}
            aria-describedby="${describedBy}"
          >
          ${config.helperText ? `<p class="field-help" id="${helperId}">${config.helperText}</p>` : ""}
          <p class="field-error" id="${errorId}" aria-live="polite"></p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="form-panel" aria-labelledby="contact-form-title">
          <h2 id="contact-form-title">Send a support request</h2>
          <p class="form-intro">
            Share a few details and our team will follow up with next steps.
          </p>
          <form id="support-form" novalidate>
            ${fieldConfigs.map(FormField).join("")}
            <p class="status-banner" id="form-status" aria-live="polite"></p>
            <button class="submit-button" type="submit">Submit request</button>
          </form>
        </section>
      `;
    }

    function SupportPage() {
      return `
        <a class="skip-link" href="#main-content">Skip to main content</a>
        <div class="page-shell">
          <main id="main-content" tabindex="-1">
            <div class="support-layout">
              <section class="hero-panel" aria-labelledby="page-title">
                <div>
                  <span class="eyebrow">Support team</span>
                  <h1 id="page-title">Contact support with confidence.</h1>
                  <p class="hero-copy">
                    Use the form to reach our product specialists for account, billing, or technical questions.
                    We review every message and respond with practical next steps.
                  </p>
                </div>
                <div class="contact-points" aria-label="Support service details">
                  <article class="contact-card">
                    <p class="contact-label">Average first response</p>
                    <p class="contact-details">Within one business day</p>
                  </article>
                  <article class="contact-card">
                    <p class="contact-label">Coverage</p>
                    <p class="contact-details">Product, billing, and access help</p>
                  </article>
                </div>
              </section>
              ${ContactForm()}
            </div>
          </main>
          <footer>
            Support requests are handled securely and only used to respond to your inquiry.
          </footer>
        </div>
      `;
    }

    function validateField(fieldName, value) {
      const trimmedValue = value.trim();

      if (fieldName === "fullName") {
        if (!trimmedValue) {
          return "Enter your full name.";
        }
        return "";
      }

      if (fieldName === "email") {
        if (!trimmedValue) {
          return "Enter your email address.";
        }

        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(trimmedValue)) {
          return "Enter a valid email address.";
        }
        return "";
      }

      if (fieldName === "phone") {
        if (!trimmedValue) {
          return "";
        }

        const phonePattern = /^\+?[0-9()\-\s.]{7,20}$/;
        const digitsOnly = trimmedValue.replace(/\D/g, "");
        if (!phonePattern.test(trimmedValue) || digitsOnly.length < 7) {
          return "Use a valid phone number, such as (555) 123-4567.";
        }
      }

      return "";
    }

    function updateFieldUI(fieldName) {
      const input = document.getElementById(fieldName);
      const errorNode = document.getElementById(fieldName + "-error");
      const config = fieldConfigs.find((field) => field.name === fieldName);
      const helperId = config && config.helperText ? config.id + "-help" : "";
      const errorId = fieldName + "-error";
      const hasError = Boolean(state.errors[fieldName]);

      input.value = state.values[fieldName];
      input.setAttribute("aria-invalid", String(hasError));
      input.setAttribute(
        "aria-describedby",
        [helperId, errorId].filter(Boolean).join(" ")
      );

      errorNode.textContent = state.errors[fieldName] || "";
    }

    function syncStatusMessage() {
      if (!state.submitted) {
        updateStatus("");
        return;
      }

      const hasErrors = fieldConfigs.some(
        (field) => Boolean(validateField(field.name, state.values[field.name]))
      );

      if (hasErrors) {
        updateStatus("Please correct the highlighted fields and submit again.");
        return;
      }

      updateStatus("");
    }

    function updateStatus(message, status = "") {
      const statusNode = document.getElementById("form-status");
      statusNode.textContent = message;
      if (status) {
        statusNode.dataset.status = status;
      } else {
        delete statusNode.dataset.status;
      }
    }

    function validateAllFields() {
      const nextErrors = {};

      fieldConfigs.forEach((field) => {
        const error = validateField(field.name, state.values[field.name]);
        if (error) {
          nextErrors[field.name] = error;
        }
      });

      state.errors = nextErrors;
      fieldConfigs.forEach((field) => updateFieldUI(field.name));
      return nextErrors;
    }

    function bindForm() {
      const form = document.getElementById("support-form");

      fieldConfigs.forEach((field) => {
        const input = document.getElementById(field.name);
        input.addEventListener("input", (event) => {
          state.values[field.name] = event.target.value;
          state.errors[field.name] = validateField(field.name, event.target.value);
          updateFieldUI(field.name);
          syncStatusMessage();
        });

        input.addEventListener("blur", (event) => {
          state.values[field.name] = event.target.value;
          state.errors[field.name] = validateField(field.name, event.target.value);
          updateFieldUI(field.name);
          syncStatusMessage();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        const errors = validateAllFields();
        const firstInvalidField = fieldConfigs.find((field) => errors[field.name]);

        if (firstInvalidField) {
          updateStatus("Please correct the highlighted fields and submit again.");
          document.getElementById(firstInvalidField.name).focus();
          return;
        }

        updateStatus("Thanks. Your support request has been submitted.", "success");
        form.reset();
        state.submitted = false;
        state.values = {
          fullName: "",
          email: "",
          phone: ""
        };
        state.errors = {};
        fieldConfigs.forEach((field) => updateFieldUI(field.name));
      });
    }

    function render() {
      document.getElementById("app").innerHTML = SupportPage();
      bindForm();
    }

    render();
  </script>
</body>
</html>
